  values ('ME', 'short_answer', 'How do you convert the following?

a) A galvanometer into an ammeter (1.5 marks)', 'a) Galvanometer to ammeter: connect a very low resistance, called a shunt (S), in parallel with the galvanometer. Most of the current flows through the shunt and only the safe full-scale current Ig passes through the coil. S = Ig × G/(I − Ig), where G is the galvanometer resistance and I the maximum current to be measured. The ammeter then has a very low resistance and is connected in series in the circuit.', null, '[{"point": "Connect a low resistance (shunt) in parallel with the galvanometer", "marks": 0.5}, {"point": "S = Ig G/(I − Ig), so most current bypasses the coil; the ammeter has very low resistance and is connected in series", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 1.5,
    162, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper II (Technical, Medical Science): BCSE 2013, batch 1", "source": {"title": "BCSE 2013 Main Examination, Technical Paper II, Medical Science", "year": 2013, "url": "https://rcsc.gov.bt/technical-paper-ii/"}}'::jsonb, 'me-technical-2-medsci2013-s7', 1, null, (select id from public.subject_groups where code = 'medical-science'), null, null)
